import { doc, setDoc } from 'firebase/firestore';
import { getFinanceDb } from '@/integrations/firebase/client';
import { buildSourceKey } from '@/lib/ledger/postingService';

const round2 = (n: number) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;

function receiptDocId(sourceKey: string): string {
  return `auto_${sourceKey.replace(/[^a-zA-Z0-9]+/g, '_').slice(0, 120)}`;
}

export async function upsertAutoPaymentReceiptDoc(input: {
  storeId: string;
  sourceType: string;
  sourceId: string;
  sourceKey: string;
  direction: 'in' | 'out';
  amount: number;
  date: string;
  method: string;
  partyName: string;
  currency?: string;
  notes?: string;
  journalEntryId?: string;
  voucherNumber?: string;
}): Promise<string> {
  const db = getFinanceDb();
  const docId = receiptDocId(input.sourceKey);
  const now = new Date().toISOString();
  const payload: Record<string, unknown> = {
    storeId: input.storeId,
    amount: round2(input.amount),
    paymentDate: input.date,
    paymentMethod: input.method || 'cash',
    currency: input.currency || 'USD',
    notes: input.notes || null,
    date: now,
    createdAt: now,
    updatedAt: now,
    autoGenerated: true,
    direction: input.direction,
    sourceType: input.sourceType,
    sourceId: input.sourceId,
    sourceKey: input.sourceKey,
    ...(input.journalEntryId ? { journalEntryId: input.journalEntryId } : {}),
    ...(input.voucherNumber ? { voucherNumber: input.voucherNumber } : {}),
  };

  if (input.direction === 'out') {
    payload.vendor = input.partyName;
    payload.clientName = input.partyName;
  } else {
    payload.clientName = input.partyName;
  }

  await setDoc(doc(db, 'stores', input.storeId, 'financeReceipts', docId), payload, { merge: true });
  return docId;
}

export function paymentSourceKey(sourceType: string, sourceId: string, event: string): string {
  return buildSourceKey(sourceType, sourceId, event);
}
